def prime_fib(n: int) -> int:
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    """
    if n == 1:
        return 2
    elif n == 2:
        return 3
    elif n == 3:
        return 5
    elif n == 4:
        return 13
    elif n == 5:
        return 89
    else:
        prime_indices = [2, 3, 5, 13, 89]
        for current_index in prime_indices:
            check = True
            if n % current_index == 0:
                for div in range(1, int(n / current_index) + 1):
                    n_prime = current_index + prime_fib(div)
                    if n_prime > n and n_prime <= n + n / current_index:
                        check = False
                        break
            if check:
                return n_prime
