def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits to the right and return the result as a string.
    If shift > number of digits, reverse the result.
    >>> circular_shift(12, 1)
    "21"
    >>> circular_shift(12, 2)
    "12"
    """
    if x >= 10**len(str(x)):
        return '-' + '-'.join(reversed(str(shift % len(str(x)))) + '-' * (len(str(x))-len(str(x)) - shift % len(str(x)))) + str(x)
    else:
        return '-' + '0'.join(reversed(str(x - shift))) + '-' * shift + str(x)

