def total_match(lst1, lst2):
    result = []
    l1_len, l2_len = len(lst1), len(lst2)

    # Initialize counters for chars less than any element in lst1 or lst2
    less_count = float('inf')
    same_count = 0

    for char in lst1:
        if char < lst2[0]:
            less_count = min(less_count, l1_len - 1 - l2_len + 1)
        elif len(lst1) - 1 + less_count > l2_len:
            return lst1

    # Compare remaining parts
    for idx in range(len(lst1)):
        if less_count >= lst2[idx]:
            less_count -= 1
            same_count += 1
        else:
            break

    # Add remaining chars from lst2 as the last element
    while same_count < len(lst2):
        result.append(lst2[same_count])
        same_count += 2

    return result

