def tri(n):
    # Using recursion to calculate the Tribonacci sequence up to the n-th term
    def tribonacci(n):
        # Base cases
        if n == 1:
            return 3
        elif n == 2:
            return 1 + 3 / 2
        elif n % 2 == 0:
            return 1 + 3 / 2 + tribonacci(n - 2)
        else:
            # If n is odd
            return 1 + 3 / 2 + tribonacci(n - 1) + tribonacci(n - 2)

