def int_to_mini_roman(number):
    # Define the mapping of integers to their roman numerals
    romans = {
        1000: 'm', 900: 'cm', 500: 'd', 400: 'cd',
        100: 'c', 90: 'xc', 50: 'l', 40: 'xl',
        10: 'x', 9: 'ix', 5: 'v', 4: 'iv', 1: 'i'
    }

    result = []

    # Loop through the mapping to add the corresponding roman numeral to the result list
    for value, numeral in romans.items():
        while number >= value:
            result.append(numeral)
            number -= value

    # Convert the result list to lowercase and join it into a single string
    return ''.join(result).lower()
